vec2 uv3 = uv2; //Krausen nur mit uv
dx = lum(GetPixel(uv3+hor) - GetPixel(uv3-hor).xy);
dy = lum(GetPixel(uv3+ver) - GetPixel(uv3-ver).xy);
//dx = 0; dy = 0;
dx *=1; dy *= 1;;
float f1 = .15+.1*q28;
vec2 uv4 = uv2+uTime / 100.0;
dx += f1*(texture(sampler_noise_hq,uv4).x-.5);
dy += f1*(texture(sampler_noise_hq,uv4).y-.5);
color =  .9+.1*roam_cos;
vec2 dz = vec2 (dx,dy);
zz = dz;
vec3 crisp= texture(sampler_main,uv+zz*.04);
vec3 crisp2 = texture(sampler_main,uv);
crisp += crisp2;
crisp *= .5;
crisp +=.05*color - length(zz)*.3;
ret1 = crisp;
ret = ret1 * .97 -  .015 ;
}

